const modules=[
 ['Sumas de Riemann','Aproximaciones izquierda, derecha y punto medio mediante rectángulos.','riemann'],['Regla del Trapecio','Una aproximación que une los puntos de la curva con segmentos.','trap'],['Regla del Punto Medio','Rectángulos construidos desde el valor central de cada intervalo.','mid'],['Regla de Simpson','Aproximación con parábolas; el número de subintervalos debe ser par.','simpson'],['Integral definida y área','El Teorema Fundamental del Cálculo convierte acumulación en evaluación.','area'],['Integración directa','Antiderivadas elementales y su interpretación gráfica.','direct'],
 ['Sustitución / potencias','Próximamente: Fase 2','future'],['Exponenciales','Próximamente: Fase 2','future'],['Logarítmicas','Próximamente: Fase 2','future'],['Trigonométricas','Próximamente: Fase 2','future'],['Trigonométricas inversas','Próximamente: Fase 3','future'],['Hiperbólicas inversas','Próximamente: Fase 3','future'],['Trinomio ax² + bx + c','Próximamente: Fase 3','future'],['Integración por partes','Próximamente: Fase 3','future']];
let current=0; const $=s=>document.querySelector(s); const f=x=>x*x;
function nav(){ $('#moduleNav').innerHTML=modules.map((m,i)=>`<a class="module ${i===current?'active':''}" style="text-decoration:none" href="modulos/modulo-${i+1}/index.html">${i+1}. ${m[0]}<small>${i>5?'Fase 2/3':'Disponible'}</small></a>`).join(''); }
function control(extra=''){return `<div class="controls"><label>Subintervalos n<input id="n" type="number" min="2" max="60" step="1" value="${extra==='simpson'?8:6}"></label><label>Límite inferior a<input id="a" type="number" value="0"></label><label>Límite superior b<input id="b" type="number" value="2"></label><button id="go">Actualizar visualización</button></div>`}
function values(a,b,n){let h=(b-a)/n,x=Array.from({length:n+1},(_,i)=>a+i*h);return{x,h, left:x.slice(0,-1).reduce((s,v)=>s+f(v)*h,0),right:x.slice(1).reduce((s,v)=>s+f(v)*h,0),mid:Array.from({length:n},(_,i)=>f(a+(i+.5)*h)*h).reduce((s,v)=>s+v,0)}}
function plotNumerical(type){let a=+$('#a').value,b=+$('#b').value,n=+$('#n').value;if(!(b>a&&n>0)){return} if(type==='simpson'&&n%2){n++;$('#n').value=n}let v=values(a,b,n), pts=Array.from({length:241},(_,i)=>a+(b-a)*i/240), data=[{x:pts,y:pts.map(f),mode:'lines',line:{color:'#0b3558',width:3},name:'f(x)=x²'}], shapes=[]; for(let i=0;i<n;i++){let x0=v.x[i],x1=v.x[i+1],m=(x0+x1)/2;if(type==='riemann'){let y=f(m);shapes.push({type:'rect',x0,x1,y0:0,y1:y,fillcolor:'rgba(243,184,75,.38)',line:{color:'#c58b1b'}})}else if(type==='mid'){let y=f(m);shapes.push({type:'rect',x0,x1,y0:0,y1:y,fillcolor:'rgba(14,107,115,.25)',line:{color:'#0e6b73'}})}else if(type==='trap'){data.push({x:[x0,x1],y:[f(x0),f(x1)],mode:'lines',line:{color:'#f3b84b',width:2},showlegend:false})}else {let q=[x0,m,x1],coef=[f(x0),f(m),f(x1)];data.push({x:Array.from({length:15},(_,j)=>x0+(x1-x0)*j/14),y:Array.from({length:15},(_,j)=>{let t=j/14;return coef[0]*(2*t*t-3*t+1)+coef[1]*4*t*(1-t)+coef[2]*(2*t*t-t)}),mode:'lines',line:{color:'#f3b84b',width:2},showlegend:false})}}
 let approx=type==='riemann'?v.mid:type==='mid'?v.mid:type==='trap'?v.h*(.5*f(a)+v.x.slice(1,-1).reduce((s,x)=>s+f(x),0)+.5*f(b)):v.h/3*(f(a)+f(b)+v.x.slice(1,-1).reduce((s,x,i)=>s+(i%2?4:2)*f(x),0)); $('#result').textContent=`Aproximación: ${approx.toFixed(6)} · valor exacto de ∫x² dx: ${((b**3-a**3)/3).toFixed(6)}`;Plotly.newPlot('plot',data,{margin:{t:28,l:48,r:12,b:42},font:{color:'#f5f5f7'},xaxis:{title:'x',gridcolor:'#3a3a3c'},yaxis:{title:'f(x)',gridcolor:'#3a3a3c'},shapes,showlegend:true,paper_bgcolor:'#1c1c1e',plot_bgcolor:'#1c1c1e'},{responsive:true});}
function numerical(kind){let names={riemann:'Sumas de Riemann',trap:'Regla del Trapecio',mid:'Regla del Punto Medio',simpson:'Regla de Simpson'}, theory={riemann:'Divide [a,b] en partes iguales. En esta demostración se usan rectángulos de punto medio; cambia n y observa cómo mejora la aproximación.',trap:'Cada subintervalo se reemplaza por un trapecio. La suma pondera los valores interiores dos veces.',mid:'Cada rectángulo tiene altura f((xᵢ₋₁+xᵢ)/2). Suele ser más preciso que los extremos para curvas suaves.',simpson:'Simpson combina valores en extremos, índices pares e impares. Requiere n par y aproxima cada tramo mediante una parábola.'};let formula=kind==='trap'?'\\(T_n=\\frac{\\Delta x}{2}[f(x_0)+2\\sum f(x_i)+f(x_n)]\\)':kind==='simpson'?'\\(S_n=\\frac{\\Delta x}{3}[f(x_0)+4\\sum_{i\\,impar}f(x_i)+2\\sum_{i\\,par}f(x_i)+f(x_n)]\\)':'\\(M_n=\\Delta x\\sum f(\\bar{x}_i),\\;\\bar{x}_i=\\frac{x_{i-1}+x_i}{2}\\)'; $('#content').innerHTML=`<div class="grid"><article class="card"><span class="tag">Idea clave</span><h3>${names[kind]}</h3><p>${theory[kind]}</p><div class="formula">${formula}</div><h3>Ejemplos resueltos</h3><ol class="steps"><li><strong>Ejemplo 1: \(\\int_0^2x^2dx\).</strong> Tome \(n=4\), \(\\Delta x=1/2\), evalúe los nodos (o puntos medios) y multiplique la suma por \(1/2\). Compare con el valor exacto \(8/3\).</li><li><strong>Ejemplo 2: \(\\int_0^1e^x dx\).</strong> Divida en \(n\) partes, construya la tabla \(x_i,f(x_i)\), aplique los pesos del método y contraste con \(e-1\).</li></ol></article><article class="card"><h3>Explorador: \(f(x)=x^2\)</h3>${control(kind)}<p class="result" id="result"></p></article><article class="card wide"><div id="plot" class="plot" aria-label="Gráfica interactiva"></div></article></div>`;$('#go').onclick=()=>plotNumerical(kind);plotNumerical(kind)}
function area(){ $('#content').innerHTML=`<div class="grid"><article class="card"><span class="tag">Teorema Fundamental</span><h3>De antiderivada a área</h3><p>Si \(F'(x)=f(x)\), entonces \(\\int_a^b f(x)dx=F(b)-F(a)\). Cuando f es negativa, el área geométrica exige integrar \(|f(x)|\).</p><div class="formula">\(A=\\int_a^b|f(x)-g(x)|dx\)</div><h3>Ejemplos resueltos</h3><ol class="steps"><li><strong>Área bajo curva:</strong> \(\\int_0^2(3x^2-2x+1)dx=[x^3-x^2+x]_0^2=6\).</li><li><strong>Entre curvas:</strong> \(x^2=2x\Rightarrow x=0,2\). En \([0,2]\), \(2x\\ge x^2\); por tanto \(A=\\int_0^2(2x-x^2)dx=4/3\).</li></ol></article><article class="card"><h3>Ajuste los límites</h3>${control()}<p class="result" id="result"></p></article><article class="card wide"><div id="plot" class="plot"></div></article></div>`;function go(){let a=+$('#a').value,b=+$('#b').value;if(b<=a)return;let xs=Array.from({length:240},(_,i)=>a+(b-a)*i/239);let exact=(b**3-a**3)/3;$('#result').textContent=`Integral firmada para f(x)=x²: ${exact.toFixed(6)}`;Plotly.newPlot('plot',[{x:xs,y:xs.map(f),fill:'tozeroy',line:{color:'#64d2ff'},fillcolor:'rgba(10,132,255,.32)',name:'Área bajo x²'}],{margin:{t:28,l:48,r:12,b:42},font:{color:'#f5f5f7'},xaxis:{title:'x',gridcolor:'#3a3a3c'},yaxis:{title:'f(x)',gridcolor:'#3a3a3c'},paper_bgcolor:'#1c1c1e',plot_bgcolor:'#1c1c1e'},{responsive:true})}$('#go').onclick=go;go()}
function direct(){ $('#content').innerHTML=`<div class="grid"><article class="card"><span class="tag">Antiderivadas</span><h3>Integración directa</h3><p>Se integra término a término y se añade la constante C. Una verificación útil consiste en derivar el resultado.</p><div class="formula">\(\\int x^n dx=\\frac{x^{n+1}}{n+1}+C\), \(n\\ne-1\)<br>\(\\int dx/x=\\ln|x|+C\)</div><h3>Tres ejemplos resueltos</h3><ol class="steps"><li>\(\\int(3/x^2-9\\sqrt{x})dx=\\int(3x^{-2}-9x^{1/2})dx=-3/x-6x^{3/2}+C\).</li><li>\(\\int(x+4\\sqrt{x}-4/x)dx=x^2/2+(8/3)x^{3/2}-4\\ln|x|+C\).</li><li>\(\\int(x-1)(x+1)dx=\\int(x^2-1)dx=x^3/3-x+C\).</li></ol></article><article class="card"><h3>Función y antiderivada</h3><p>Selecciona un caso y compara \(f(x)\) con una antiderivada \(F(x)\).</p><div class="controls"><label>Ejemplo<select id="case"><option value="power">f(x)=x²</option><option value="linear">f(x)=2x+1</option><option value="root">f(x)=√x</option></select></label><button id="go">Mostrar gráficas</button></div><p class="result" id="result"></p></article><article class="card wide"><div id="plot" class="plot"></div></article></div>`;function go(){let c=$('#case').value,fun,F,text;c==='power'?(fun=x=>x*x,F=x=>x**3/3,text='F(x)=x³/3 + C'):c==='linear'?(fun=x=>2*x+1,F=x=>x*x+x,text='F(x)=x²+x+C'):(fun=x=>Math.sqrt(Math.max(0,x)),F=x=>2*Math.max(0,x)**1.5/3,text='F(x)=2x³ᐟ²/3+C');let xs=Array.from({length:240},(_,i)=>-1+4*i/239);$('#result').textContent=text;Plotly.newPlot('plot',[{x:xs,y:xs.map(fun),name:'f(x)',line:{color:'#64d2ff',width:3}},{x:xs,y:xs.map(F),name:'F(x)',line:{color:'#ffd60a',width:3}}],{margin:{t:28,l:48,r:12,b:42},font:{color:'#f5f5f7'},paper_bgcolor:'#1c1c1e',plot_bgcolor:'#1c1c1e',legend:{orientation:'h'}},{responsive:true})}$('#go').onclick=go;go()}
function math(){if(window.renderMathInElement)renderMathInElement($('#content'),{delimiters:[{left:'$$',right:'$$',display:true},{left:'\\(',right:'\\)',display:false}]})}
function render(i){current=i;nav();let m=modules[i];$('#title').textContent=`${i+1}. ${m[0]}`;$('#lead').textContent=m[1];if(m[2]==='future'){$('#content').innerHTML=`<section class="placeholder"><span class="tag">${m[1]}</span><h3>Este espacio ya está reservado</h3><p>La arquitectura conserva la navegación para que la siguiente fase se integre sin cambiar el recorrido de aprendizaje.</p></section>`}else if(['riemann','trap','mid','simpson'].includes(m[2]))numerical(m[2]);else if(m[2]==='area')area();else direct();setTimeout(math,0);window.scrollTo({top:0,behavior:'smooth'})}
$('.menu').onclick=()=>document.querySelector('aside').classList.toggle('open');render(Math.max(0,Math.min(13,(Number(new URLSearchParams(location.search).get('mod'))||1)-1)));window.addEventListener('load',math);
